-- Données de référence du service credits : les lignes de l'import.sql du legacy pour LOANS (2), LOAN_REPAYMENTS (18),
-- CREDIT_SCORES (4) et RISK_PROFILES (4), identifiants, valeurs et dates repris tels quels (dates et heures de
-- l'import lues à l'heure de Paris). Prêt 1 AUTO 12000.00 sur 48 mois (12 échéances dans l'import), prêt 2 TRAVAUX
-- 5000.00 sur 24 mois (6 échéances dans l'import).
-- Hors migrations : chargé dans une base déjà migrée par Flyway (make reset-data), jamais en production.
-- Colonnes legacy sans équivalent cible : aucune.
select setval(pg_get_serial_sequence('loans', 'id'), (select max(id) from loans));

select setval(pg_get_serial_sequence('loan_repayments', 'id'), (select max(id) from loan_repayments));

select setval(pg_get_serial_sequence('credit_scores', 'id'), (select max(id) from credit_scores));

select setval(pg_get_serial_sequence('risk_profiles', 'id'), (select max(id) from risk_profiles));
